nodes.declaration:
VAR_GLOBAL
 value : BOOL;
 result : BOOL;
 ib_启动 AT%IX0.7 :BOOL;
END_VAR

PROGRAM Main
VAR
 value : BOOL;
 a, b : Motor;
END_VAR

nodes.implementation:
// result and missing are comment text, not references
value := TRUE;
GVL.value := value;
a(enable := value, active => result);
b(enable := GVL.value);
result := a.active OR b.active;
IF ib_启动 THEN
 value := FALSE;
END_IF
